head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDSTF76120";
scwin.G_vertical = '\u000B';
scwin.G_formfeed = '\u000C';
scwin.editor = undefined;
scwin.upload = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — status
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame, $c.frame.Provider
    try {
        const status = (String(((dma_pageContext.get("status") ?? "")) == null ? '' : ((dma_pageContext.get("status") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("status") ?? "")) == null ? '' : ((dma_pageContext.get("status") ?? ""))));
        if ("update" === status) {
            let fn_search = $c.win.getParent().fn_search;
            fn_search();  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_search — as-is 정의 없음(원본 JS 미제공 — 회신)
            await $c.win.alert("수정되었습니다.");
        } else {
            if ("register" === status) {
                fn_search = $c.win.getParent().fn_search;
                fn_search();  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_search — as-is 정의 없음(원본 JS 미제공 — 회신)
                await $c.win.alert("등록되었습니다.");
            } else {
                if ("delete" === status) {
                    fn_search = $c.win.getParent().fn_search;
                    fn_search();  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_search — as-is 정의 없음(원본 JS 미제공 — 회신)
                    await $c.win.alert("삭제되었습니다.");
                    $c.win.closePopup();
                }
            }
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf76120.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.editor =new Dext5editor("dext5editor1"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf76120' }); }

try { scwin.upload =new Dext5Upload("dext5upload"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf76120' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_loadList();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf76120.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_update_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_update_onclick = async function(e){
    try {
        await scwin.update()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf76120.btn_update_onclick' }); }
};

/**
 * @method
 * @name btn_del_onclick
 * @description 「삭제」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_del_onclick = async function(e){
    try {
        await scwin.del()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf76120.btn_del_onclick' }); }
};

/**
 * @method
 * @name btn_frame_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_frame_onclick = function(e){
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf76120.btn_frame_onclick' }); }
};

/**
 * @method
 * @name DEXT5UPLOAD_OnCreationComplete
 * @description DEXT5 UPLOAD On Creation Complete 처리
 * @returns {void}
 * @hidden N
 */
scwin.DEXT5UPLOAD_OnCreationComplete = function () {
    try {
        const attachStr = "" + dma_noticeDetail.get("attachString") + "";
        if (attachStr.length > 0) {
            const temp1 = attachStr.split(scwin.G_vertical, 20);
            for (let i = 0; i < temp1.length - 1; i++) {
                const temp2 = temp1[i].split(scwin.G_formfeed, 20);
                DEXT5UPLOAD.AddUploadedFile(temp2[0], temp2[2], temp2[4], temp2[3], temp2[1], 'dext5upload');
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf76120.DEXT5UPLOAD_OnCreationComplete" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_dext5FileDown_ajaxsubmit
 * @description dext5 File Down ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_dext5FileDown_ajaxsubmit = async function () {
    try { return await $c.data.downFile("/ods/dext5.do", "", ($c.util.getComponent("dma_dext5FileDownAjaxsubmitReq") ? $c.util.getComponent("dma_dext5FileDownAjaxsubmitReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/ods/dext5.do",
        ref: "dma_loadListReq",
        target: "dlt_chrgInstList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function () {
    const sprtRoomtitle = $c.util.getComponent('ipt_sprtRoomtitle').getValue();
    if ($.trim(sprtRoomtitle).length === 0) {
        await $c.win.alert("제목을 입력해 주세요.");
        ($c.util.getComponent('ipt_sprtRoomtitle') && $c.util.getComponent('ipt_sprtRoomtitle').setFocus ? $c.util.getComponent('ipt_sprtRoomtitle').setFocus() : $c.util.getComponent('ipt_sprtRoomtitle').focus());
        return;
    }
    if (DEXT5.isEmpty("dext5editor1")) {
        await $c.win.alert("내용을 입력해 주세요.");
        DEXT5.setFocusToEditor("dext5editor1");
        return;
    }
    DEXT5UPLOAD.Transfer("dext5upload");
};

/**
 * @method
 * @name DEXT5UPLOAD_OnTransfer_Complete
 * @description DEXT5 UPLOAD On Transfer Complete 처리
 * @param {String} dextId dextId
 * @returns {void}
 * @hidden N
 */
scwin.DEXT5UPLOAD_OnTransfer_Complete = function (dextId) {
    const textNew = DEXT5UPLOAD.GetNewUploadListForText("dext5upload");
    if (textNew != null) {
        let rtn = fn_newTextToString(textNew);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_newTextToString — 타 모듈 as-is 공통(stf/ods·ins/hindr) — 반입 범위 밖
        $('#ipt_attachFileInfo', $('#updateForm')).val(rtn);
    }
    const textDel = DEXT5UPLOAD.GetDeleteListForText("dext5upload");
    if (textDel != null) {
        rtn = fn_delTextToString(textDel);  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_delTextToString — 타 모듈 as-is 공통(stf/ods·ins/hindr) — 반입 범위 밖
        $('#ipt_deleteFileInfo', $('#updateForm')).val(rtn);
    }
    $('#ipt_SCREN_ID', $('#updateForm')).val("/ui/jsp/JLDSTF76120.xml");
    $('#ipt_method', $('#updateForm')).val("updateSprtRoom");
    const htmlText = DEXT5.getBodyValue("dext5editor1");
    $c.util.getComponent('ipt_sprtRoomContn').setValue(htmlText);
    const notHtmlText = DEXT5.getBodyTextValue("dext5editor1");
    $c.util.getComponent('ipt_sprtRoomContnNoHtml').setValue(notHtmlText);
    $c.util.getComponent('ipt_ldMktTpCd').setValue($('#slc_selLdMktTpCd option:selected').val());
    $('#updateForm').submit();
};

/**
 * @method
 * @name del
 * @description del 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.del = async function () {
    if (await $c.win.confirm("삭제하시겠습니까?")) {
        $('#ipt_SCREN_ID', $('#updateForm')).val("/ui/jsp/JLDSTF76120.xml");
        $('#ipt_method', $('#updateForm')).val("delSprtRoom");
        $('#ipt_SCREN_PROCES_TP_CD', $('#updateForm')).val("04");
        $('#updateForm').submit();
    }
};

/**
 * @method
 * @name dext_editor_loaded_event
 * @description dext editor loaded event 처리
 * @param {*} editor editor
 * @returns {void}
 * @hidden N
 */
scwin.dext_editor_loaded_event = function (editor) {
    DEXT5.setHtmlValueEx($c.util.getComponent('ipt_webSprtRoomContn').getValue(), "dext5editor1");
};

/**
 * @method
 * @name DEXT5UPLOAD_BeforeFileDownload
 * @description DEXT5 UPLOAD Before File Download 처리
 * @param {String} uploadID uploadID
 * @param {*} strWebFile strWebFile
 * @param {*} strItemKey strItemKey
 * @param {*} strItemOrgName strItemOrgName
 * @param {*} strItemUrlOrPath strItemUrlOrPath
 * @param {*} strLargeFiles strLargeFiles
 * @param {*} strIsLastEvent strIsLastEvent
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.DEXT5UPLOAD_BeforeFileDownload = async function (uploadID, strWebFile, strItemKey, strItemOrgName, strItemUrlOrPath, strLargeFiles, strIsLastEvent) {
    let retVal = true;

    if (download_file_list === '') {
        download_file_list += strItemUrlOrPath;
        download_file_keys += strItemKey;
    } else {
        download_file_list += scwin.G_vertical + strItemUrlOrPath;
        download_file_keys += scwin.G_vertical + strItemKey;
    }
    if (strIsLastEvent === 1) {
        $c.util.getComponent('ipt_sprtRoomNoAttachSeq').setValue(download_file_keys);
        $c.util.getComponent('ipt_fileList').setValue(download_file_list);
        download_file_list = '';
        download_file_keys = '';
        await scwin.dext5FileDown();
        retVal = false;
    }
    return retVal;
};

/**
 * @method
 * @name dext5FileDown
 * @description dext5 File Down 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dext5FileDown = async function () {
    await scwin.tx_dext5FileDown_ajaxsubmit();
};

/**
 * @method
 * @name fnCallDext5
 * @description fn Call Dext5 처리
 * @param {*} result result
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnCallDext5 = async function (result) {
    if (result.fileStatus === 'ok') {
        DEXT5UPLOAD.UPLOADTOP.G_CURRUPLOADER._config.useDownloadEvent = "0";
        DEXT5UPLOAD.DownloadFile("dext5upload");
    } else {
        await $c.win.alert("파일다운로드 중 오류가 발생하였습니다. 관리자에게 문의하시기 바랍니다.");
    }
    DEXT5UPLOAD.UPLOADTOP.G_CURRUPLOADER._config.useDownloadEvent = "1";
};
